import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CoreFunction.functionCeiling
 */
public class CoreFunction_functionCeiling_TriageGen2Test {

    private CoreFunction coreFunction;
    private EvalContext mockContext;
    private Expression mockArg1;
    private Method functionCeilingMethod;

    @Before
    public void setUp() throws Exception {
        mockContext = mock(EvalContext.class);
        mockArg1 = mock(Expression.class);

        // CoreFunction constructor requires functionCode and Expression array
        // We use a dummy code and an array containing our mock expression
        Expression[] args = new Expression[]{mockArg1};
        coreFunction = new CoreFunction(1, args);

        // Access the protected method via reflection
        functionCeilingMethod = CoreFunction.class.getDeclaredMethod("functionCeiling", EvalContext.class);
        functionCeilingMethod.setAccessible(true);
    }

    /**
     * Helper to invoke the protected method
     */
    private Object invokeFunctionCeiling(EvalContext context) throws Exception {
        return functionCeilingMethod.invoke(coreFunction, context);
    }

    @Test
    public void testFunctionCeiling_PositiveDouble() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(2.3);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(3.0), result);
    }

    @Test
    public void testFunctionCeiling_NegativeDouble() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(-2.3);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        // Math.ceil(-2.3) is -2.0
        assertEquals(new Double(-2.0), result);
    }

    @Test
    public void testFunctionCeiling_Integer() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(5.0);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(5.0), result);
    }

    @Test
    public void testFunctionCeiling_Zero() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(0.0), result);
    }

    @Test
    public void testFunctionCeiling_NegativeZero() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(-0.0);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(-0.0), result);
    }

    @Test
    public void testFunctionCeiling_LargeValue() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(Double.MAX_VALUE);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(Double.MAX_VALUE), result);
    }

    @Test
    public void testFunctionCeiling_Infinity() throws Exception {
        // Arrange
        when(mockArg1.computeValue(mockContext)).thenReturn(Double.POSITIVE_INFINITY);

        // Act
        Object result = invokeFunctionCeiling(mockContext);

        // Assert
        assertEquals(new Double(Double.POSITIVE_INFINITY), result);
    }

    @Test(expected = Exception.class)
    public void testFunctionCeiling_WrongArgumentCount() throws Exception {
        // Create a core function with 0 arguments to trigger assertArgCount(1) failure
        CoreFunction emptyFunction = new CoreFunction(1, new Expression[]{});

        // Re-map the method to the empty function instance
        Method method = CoreFunction.class.getDeclaredMethod("functionCeiling", EvalContext.class);
        method.setAccessible(true);

        // This should throw an exception because assertArgCount(1) will fail
        method.invoke(emptyFunction, mockContext);
    }
}
